import AppKit
import ImageIO
import UniformTypeIdentifiers

enum PasteboardCodec {
    static let ignoredTypes: Set<String> = [
        "org.nspasteboard.ConcealedType", "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType", "com.agilebits.onepassword"
    ]
    static let textTypes: Set<String> = [
        NSPasteboard.PasteboardType.string.rawValue, NSPasteboard.PasteboardType.rtf.rawValue,
        NSPasteboard.PasteboardType.rtfd.rawValue, NSPasteboard.PasteboardType.html.rawValue,
        NSPasteboard.PasteboardType.URL.rawValue, NSPasteboard.PasteboardType.fileURL.rawValue
    ]

    static func capture(from board: NSPasteboard, source: String) throws -> ClipCapture? {
        let version = board.changeCount
        guard let items = board.pasteboardItems, !items.isEmpty else { return nil }
        // Inspect the entire transaction before reading any item's data.
        guard !items.contains(where: { !$0.types.map(\.rawValue).filter(ignoredTypes.contains).isEmpty }) else {
            return nil
        }
        var total = 0
        var parts: [ClipPart] = []
        for item in items {
            var reps: [ClipRepresentation] = []
            for type in item.types {
                let isImage = UTType(type.rawValue)?.conforms(to: .image) == true
                guard textTypes.contains(type.rawValue) || isImage,
                      let data = item.data(forType: type), !data.isEmpty else { continue }
                total += data.count
                guard total <= HistoryRepository.maxPayloadBytes else { throw HistoryError.tooLarge }
                reps.append(ClipRepresentation(type: type.rawValue, data: data))
            }
            // Do not silently capture only some items of a multi-item clipboard.
            guard !reps.isEmpty else { return nil }
            parts.append(ClipPart(representations: reps))
        }
        guard board.changeCount == version else { return nil }
        let payload = ClipPayload(parts: parts)
        let reps = parts.flatMap(\.representations)
        let files = reps.filter { $0.type == NSPasteboard.PasteboardType.fileURL.rawValue }
        if !files.isEmpty {
            let names = files.compactMap { String(data: $0.data, encoding: .utf8) }
                .compactMap { URL(string: $0)?.lastPathComponent }
            return ClipCapture(payload: payload, kind: .files, title: names.joined(separator: ", "),
                               detail: "Files: \(files.count)", searchText: names.joined(separator: " "),
                               source: source, thumbnail: nil)
        }
        if let rep = reps.first(where: { UTType($0.type)?.conforms(to: .image) == true }) {
            let imageSource = CGImageSourceCreateWithData(rep.data as CFData, nil)
            let properties = imageSource.flatMap { CGImageSourceCopyPropertiesAtIndex($0, 0, nil) as? [CFString: Any] }
            let width = properties?[kCGImagePropertyPixelWidth] as? Int
            let height = properties?[kCGImagePropertyPixelHeight] as? Int
            let dimensions = width.flatMap { w in height.map { "\(w) × \($0)" } } ?? "Image"
            var thumbnail: Data?
            if let imageSource, let cgImage = CGImageSourceCreateThumbnailAtIndex(imageSource, 0, [
                kCGImageSourceCreateThumbnailFromImageAlways: true,
                kCGImageSourceCreateThumbnailWithTransform: true,
                kCGImageSourceThumbnailMaxPixelSize: 240
            ] as CFDictionary) {
                thumbnail = NSBitmapImageRep(cgImage: cgImage).representation(using: .png, properties: [:])
            }
            return ClipCapture(payload: payload, kind: .image, title: "Image", detail: dimensions,
                               searchText: "Image \(dimensions)", source: source, thumbnail: thumbnail)
        }
        var text = reps.first(where: { $0.type == NSPasteboard.PasteboardType.string.rawValue })
            .flatMap { String(data: $0.data, encoding: .utf8) }
        if text == nil, let rtf = reps.first(where: { $0.type == NSPasteboard.PasteboardType.rtf.rawValue }) {
            text = NSAttributedString(rtf: rtf.data, documentAttributes: nil)?.string
        }
        if text == nil {
            text = reps.first(where: { $0.type == NSPasteboard.PasteboardType.URL.rawValue })
                .flatMap { String(data: $0.data, encoding: .utf8) }
        }
        let plain = text ?? "Formatted text"
        let title = plain.split(whereSeparator: \.isNewline).prefix(3).joined(separator: " ")
        return ClipCapture(payload: payload, kind: .text,
                           title: title.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
                               ? "Whitespace and line breaks" : String(title.prefix(300)),
                           detail: "\(plain.count) characters", searchText: String(plain.prefix(100_000)),
                           source: source, thumbnail: nil)
    }

    @discardableResult
    static func restore(_ payload: ClipPayload, to board: NSPasteboard) -> Bool {
        let items = payload.parts.map { part -> NSPasteboardItem in
            let item = NSPasteboardItem()
            for rep in part.representations { item.setData(rep.data, forType: .init(rep.type)) }
            return item
        }
        guard !items.isEmpty else { return false }
        board.clearContents()
        return board.writeObjects(items)
    }
}

final class ClipboardMonitor {
    var onCapture: ((ClipCapture) -> Void)?
    var onStatus: ((String?) -> Void)?
    private let board: NSPasteboard
    private var timer: Timer?
    private var lastChange: Int
    var paused = false {
        didSet { lastChange = board.changeCount }
    }
    private var lastStatus: String?

    init(board: NSPasteboard = .general) {
        self.board = board
        lastChange = board.changeCount
    }

    func start() {
        guard timer == nil else { return }
        timer = Timer(timeInterval: 0.45, repeats: true) { [weak self] _ in self?.poll() }
        timer?.tolerance = 0.1
        RunLoop.main.add(timer!, forMode: .common)
    }

    func stop() { timer?.invalidate(); timer = nil }
    func ignoreCurrentChange() { lastChange = board.changeCount }

    func poll(userInitiated: Bool = false) {
        guard !paused else { return }
        if #available(macOS 15.4, *) {
            let behavior = board.accessBehavior
            if behavior == .alwaysDeny {
                status("Clipboard access is blocked in System Settings.")
                return
            }
            if behavior != .alwaysAllow && !userInitiated {
                status("Allow clipboard access to start saving your history.")
                return
            }
        }
        status(nil)
        let version = board.changeCount
        guard userInitiated || version != lastChange else { return }
        lastChange = version
        do {
            if let capture = try PasteboardCodec.capture(from: board,
                source: NSWorkspace.shared.frontmostApplication?.localizedName ?? "") {
                onCapture?(capture)
            }
        } catch { status(HistoryError.message(for: error)) }
    }

    private func status(_ value: String?) {
        guard lastStatus != value else { return }
        lastStatus = value
        onStatus?(value)
    }
}
